xql_query:
// ============================================================
// Rule: REPORT-FTG_Web Filter: Access to Suspicious Category
// Vendor: Fortigate
// Objective:
// Detect activity associated with REPORT-FTG_Web Filter: Access to Suspicious Category.
// Severity: SEV_030_MEDIUM
// Category: OTHER
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0010 - Exfiltration
// Tactic: TA0001 - Initial Access
// Technique: T1192 - Spearphishing Link
// Technique: T1566 - Phishing
// Tactic: TA0005 - Defense Evasion

dataset = fortinet_fortigate_raw
| filter cat = "utm:webfilter"
  and act != "blocked"
  and (
    requestContext = "Newly Observed Domain" or
    requestContext = "Newly Registered Domain"
  )
| alter
    timestamp = _time,
    src_ip = src,
    dst_ip = dst,
    category = requestContext,
    application = app,
    action_taken = act,
    log_message = msg,
    request_origin = dhost,
    user = duser,
    device_name = _reporting_device_name
| fields timestamp, device_name, src_ip, dst_ip, category, application, action_taken, log_message, request_origin, user
